  1	import type { IncomingMessage, ServerResponse } from 'node:http';
  2	import type { Router } from '../router.js';
  3	import type { AppConfig, GitCredentialEntry } from '../../config/config.types.js';
  4	import type { PollingManager } from '../pollingManager.js';
  5	import { saveConfigField } from '../../config/config.js';
  6	import { parseJsonBody, sendJson, sendError, isPlainObject } from '../requestUtils.js';
  7	import { toKebabCase } from '../../utils/slug.js';
  8	
  9	// Polling-interval bounds — shared with settings UI (gui/public/js/views/settings.js).
 10	import {
 11	    MIN_POLLING_INTERVAL_SECONDS,
 12	    MAX_POLLING_INTERVAL_SECONDS,
 13	    MIN_NOTES_CARD_HEIGHT,
 14	    MAX_NOTES_CARD_HEIGHT,
 15	    MIN_NOTES_COLUMNS,
 16	    MAX_NOTES_COLUMNS,
 17	} from '../../config/config.constants.js';
 18	
 19	// ---------------------------------------------------------------------------
 20	// Helpers
 21	// ---------------------------------------------------------------------------
 22	
 23	/**
 24	 * Masks a credential token for display in API responses.
 25	 * Shows the last 4 characters of the token prefixed with `****`.
 26	 * Tokens shorter than 4 characters are fully masked as `****`.
 27	 */
 28	function maskToken(token: string): string {
 29	    return token.length < 4 ? '****' : '****' + token.slice(-4);
 30	}
 31	
 32	/**
 33	 * Extracts and lowercases the scheme from a URL string (the part before the
 34	 * first `:`). Returns an empty string when no colon is present.
 35	 *
 36	 * @example extractScheme('https://example.com') // → 'https'
 37	 * @example extractScheme('javascript:alert(1)') // → 'javascript'
 38	 */
 39	function extractScheme(url: string): string {
 40	    const colonIdx = url.indexOf(':');
 41	    return colonIdx !== -1 ? url.slice(0, colonIdx).toLowerCase() : '';
 42	}
 43	
 44	/**
 45	 * Type guard that returns `true` when `value` is a finite integer number.
 46	 * Used by PUT route handlers to validate numeric config fields.
 47	 *
 48	 * @param value - The value to test (any type accepted).
 49	 * @returns `true` when `value` is of type `number`, finite, and an integer; `false` otherwise.
 50	 */
 51	function isValidFiniteInteger(value: unknown): value is number {
 52	    return typeof value === 'number' && Number.isFinite(value) && Number.isInteger(value);
 53	}
 54	
 55	/**
 56	 * Returns a copy of the credentials array with all tokens masked.
 57	 */
 58	function buildMaskedCredentials(
 59	    credentials: GitCredentialEntry[] | undefined,
 60	): GitCredentialEntry[] {
 61	    if (!credentials) return [];
 62	    return credentials.map((entry) => ({ ...entry, token: maskToken(entry.token) }));
 63	}
 64	
 65	/**
 66	 * Generates a unique kebab-case ID from a label, appending a numeric suffix
 67	 * (-2, -3, ...) when the base ID is already taken.
 68	 */
 69	function generateUniqueId(label: string, existingIds: Set<string>): string {
 70	    const baseId = toKebabCase(label) || 'credential';
 71	    let candidateId = baseId;
 72	    let suffix = 2;
 73	    while (existingIds.has(candidateId)) {
 74	        candidateId = `${baseId}-${suffix}`;
 75	        suffix++;
 76	    }
 77	    return candidateId;
 78	}
 79	
 80	// ---------------------------------------------------------------------------
 81	// Route registration
 82	// ---------------------------------------------------------------------------
 83	
 84	// ---------------------------------------------------------------------------
 85	// Named-options interface
 86	// ---------------------------------------------------------------------------
 87	
 88	export interface ConfigRoutesOptions {
 89	    router: Router;
 90	    appConfig: AppConfig;
 91	    /** Optional absolute path to `config.json`. Defaults to the tool-root `config.json`. */
 92	    configPath?: string;
 93	    /** Optional `PollingManager`. When provided, PUT /api/config/polling restarts the loop. */
 94	    pollingManager?: PollingManager;
 95	}
 96	
 97	/**
 98	 * Registers REST endpoints for managing application configuration in
 99	 * `config.json`.
100	 *

101	 * **Credentials endpoints:**
102	 *
103	 * | Method | Path                              | Description               |
104	 * |--------|-----------------------------------|---------------------------|
105	 * | GET    | /api/config/credentials           | List credentials (masked) |
106	 * | PUT    | /api/config/credentials           | Add / update an entry     |
107	 * | DELETE | /api/config/credentials/:id       | Remove an entry           |
108	 *
109	 * **Polling endpoints:**
110	 *
111	 * | Method | Path                    | Description                                          |
112	 * |--------|-------------------------|------------------------------------------------------|
113	 * | GET    | /api/config/polling     | Return current `gitPollingIntervalSeconds`           |
114	 * | PUT    | /api/config/polling     | Update the polling interval (min 10 s, max 86400 s)  |
115	 *
116	 * **Webserver URL endpoints:**
117	 *
118	 * | Method | Path                         | Description                              |
119	 * |--------|------------------------------|------------------------------------------|
120	 * | GET    | /api/config/webserver-url    | Return current `webserverUrl` (or null)  |
121	 * | PUT    | /api/config/webserver-url    | Update the webserver URL                 |
122	 *
123	 * **Notes display endpoints:**
124	 *
125	 * | Method | Path                          | Description                                                                                                         |
126	 * |--------|-------------------------------|---------------------------------------------------------------------------------------------------------------------|
127	 * | GET    | /api/config/notes-display     | Return current `notesCardHeight` and `notesColumns`                                                                 |
128	 * | PUT    | /api/config/notes-display     | Update notes display settings (partial updates — all fields optional). Fields: `notesCardHeight` ∈ [120, 800] (integer px), `notesColumns` ∈ [1, 6] (integer) |
129	 *
130	 * Changes take effect immediately (the in-memory `appConfig` is mutated) and
131	 * are persisted to `config.json` via `saveConfigField()`.
132	 *
133	 * **Security:** tokens are never returned in full — only the last 4 characters
134	 * are exposed. The `host` field accepts any non-empty string (no format
135	 * restriction is enforced at this layer).
136	 *
137	 * @param options - Named-options bag: `router`, `appConfig`, optional
138	 *   `configPath` (defaults to tool-root `config.json`), optional
139	 *   `pollingManager` (restarts polling loop when present).
140	 */
141	export function registerConfigRoutes(options: ConfigRoutesOptions): void {
142	    const { router, appConfig, configPath, pollingManager } = options;
143	    // ------------------------------------------------------------------
144	    // GET /api/config/credentials — list all (tokens masked)
145	    // Returns GitCredentialEntry[] with tokens masked.
146	    // ------------------------------------------------------------------
147	    router.get('/api/config/credentials', (
148	        _req: IncomingMessage,
149	        res: ServerResponse,
150	        _params: Record<string, string>,
151	    ): void => {
152	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
153	    });
154	
155	    // ------------------------------------------------------------------
156	    // PUT /api/config/credentials — add or update a single entry
157	    //
158	    // Request body: { id?: string, label: string, host: string, token: string }
159	    //
160	    // - When `id` is omitted: auto-generates a kebab-case ID from `label`,
161	    //   appending a numeric suffix (-2, -3, …) if needed to avoid collisions.
162	    //   Always creates a new entry.
163	    // - When `id` is provided and matches an existing entry: upserts (replaces)
164	    //   the existing entry in-place.
165	    // - When `id` is provided and does NOT match any existing entry: creates a
166	    //   new entry with the given ID (after checking the ID is not already taken).
167	    //
168	    // Returns 400 when the resulting ID would collide with an existing entry
169	    // that is NOT the one being updated (duplicate-ID rejection).
170	    // ------------------------------------------------------------------
171	    router.put('/api/config/credentials', async (
172	        req: IncomingMessage,
173	        res: ServerResponse,
174	        _params: Record<string, string>,
175	    ): Promise<void> => {
176	        let body: unknown;
177	        try {
178	            body = await parseJsonBody(req);
179	        } catch (err) {
180	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
181	            return;
182	        }
183	
184	        if (!isPlainObject(body)) {
185	            sendError(res, 400, 'Request body must be a JSON object.');
186	            return;
187	        }
188	
189	        const { id, label, host, token } = body as {
190	            id?: unknown;
191	            label?: unknown;
192	            host?: unknown;
193	            token?: unknown;
194	        };
195	
196	        // Validate required string fields.
197	        if (typeof label !== 'string' || label.trim() === '') {
198	            sendError(res, 400, 'Missing or invalid field "label": must be a non-empty string.');
199	            return;
200	        }
201	        if (typeof host !== 'string' || host.trim() === '') {
